<?php
 namespace Pterodactyl\Services\Dezerx\Minecraft; use Throwable; use Aternos\Nbt\Tag\CompoundTag; use Aternos\Nbt\Tag\DoubleTag; use Aternos\Nbt\Tag\FloatTag; use Aternos\Nbt\Tag\FloatValueTag; use Aternos\Nbt\Tag\IntTag; use Aternos\Nbt\Tag\IntValueTag; use Aternos\Nbt\Tag\ListTag; use Aternos\Nbt\Tag\StringTag; use Aternos\Nbt\Tag\TagType; class PlayerEditor { public static function backupSuffix(): string { return \Pterodactyl\Services\Dezerx\Brand::file('bak'); } public static function backupSuffixes(): array { return \Pterodactyl\Services\Dezerx\Brand::files('bak'); } private const GAME_MODES = ['survival' => 0, 'creative' => 1, 'adventure' => 2, 'spectator' => 3]; private const LEGACY_DIMENSIONS = ['minecraft:overworld' => 0, 'minecraft:the_nether' => -1, 'minecraft:the_end' => 1]; private const ROSTERS = ['op' => 'ops.json', 'ban' => 'banned-players.json', 'whitelist' => 'whitelist.json']; public static function editsPlayerData(string $action): bool { return !isset(self::ROSTERS[$action]); } public static function apply(ServerFiles $files, string $server, string $uuid, ?string $name, array $data): array { $action = (string) ($data['action'] ?? ''); if (isset(self::ROSTERS[$action])) { return self::roster($files, $action, $uuid, $name, (bool) ($data['on'] ?? true)); } return self::playerData($files, $server, $uuid, $data); } private static function roster(ServerFiles $files, string $action, string $uuid, ?string $name, bool $on): array { if ($name === null || preg_match('/^[A-Za-z0-9_]{1,16}$/', $name) !== 1) { return self::fail('Minecraft stores a name alongside the UUID in that list, and this player has none on this server. Start the server and use the console instead.'); } $file = self::ROSTERS[$action]; $entries = self::readList($files, $file); if ($entries === null) { return self::fail("Could not read {$file} from the server, so it was left alone.", 502); } $kept = []; foreach ($entries as $entry) { if (!is_array($entry) || strcasecmp((string) ($entry['uuid'] ?? ''), $uuid) !== 0) { $kept[] = $entry; } } if ($on) { $kept[] = match ($action) { 'op' => ['uuid' => $uuid, 'name' => $name, 'level' => 4, 'bypassesPlayerLimit' => false], 'ban' => [ 'uuid' => $uuid, 'name' => $name, 'created' => date('Y-m-d H:i:s O'), 'source' => 'Server', 'expires' => 'forever', 'reason' => 'Banned by an operator.', ], default => ['uuid' => $uuid, 'name' => $name], }; } $json = json_encode(array_values($kept), JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE); if ($json === false || !$files->writeFile("/{$file}", $json)) { return self::fail("Could not write {$file} back to the server.", 502); } return self::done(sprintf('%s %s %s %s', $on ? 'added' : 'removed', $name, $on ? 'to' : 'from', $file)); } private static function readList(ServerFiles $files, string $file): ?array { $root = $files->listFiles('/'); if ($root === null) { return null; } if (!in_array($file, array_column($root, 'name'), true)) { return []; } $raw = $files->fileContents("/{$file}"); if ($raw === null) { return null; } $raw = trim($raw); if ($raw === '') { return []; } $entries = json_decode($raw, true); return is_array($entries) ? $entries : null; } private static function playerData(ServerFiles $files, string $server, string $uuid, array $data): array { $dirs = PlayerFiles::dirs($files, $server); $listing = $files->listFiles($dirs['data']); if ($listing === null) { return self::fail("Could not read {$dirs['data']} from the server.", 502); } if (!in_array("{$uuid}.dat", array_column($listing, 'name'), true)) { return self::fail('That player has no saved data on this server yet, so there is nothing to edit. They have to join once first.'); } $path = $dirs['data'] . "/{$uuid}.dat"; $raw = $files->fileContents($path, ServerFiles::MAX_PLAYER_FILE); if ($raw === null || $raw === '' || strlen($raw) > ServerFiles::MAX_PLAYER_FILE) { return self::fail("Could not read that player's saved data.", 502); } try { [$plain, $compression] = Nbt::decompress($raw); $root = Nbt::parse($plain); $reproducible = $root instanceof CompoundTag && Nbt::serialize($root) === $plain; } catch (Throwable) { $root = null; $reproducible = false; } if (!$root instanceof CompoundTag || !$reproducible) { return self::fail('That save file is not in a shape this panel can rewrite safely. Run the action while they are online instead.', 409); } $ran = self::mutate($root, $data); if ($ran === null) { return self::fail('That action is missing something it needs.'); } try { $encoded = Nbt::compress(Nbt::serialize($root), $compression); } catch (Throwable) { return self::fail("That player's data could not be written back.", 502); } $files->writeFile($path . self::backupSuffix(), $raw); $old = array_map(fn (string $suffix) => basename($path) . $suffix, array_slice(self::backupSuffixes(), 1)); if ($old !== []) { $files->deletePaths(dirname($path), $old); } if (!$files->writeFile($path, $encoded)) { return self::fail('The node would not accept the updated player file.', 502); } return self::done($ran); } private static function mutate(CompoundTag $data, array $payload): ?string { return match ((string) ($payload['action'] ?? '')) { 'kill' => self::kill($data), 'heal' => self::heal($data), 'feed' => self::feed($data), 'starve' => self::starve($data), 'gamemode' => self::gameMode($data, (string) ($payload['mode'] ?? '')), 'teleport' => self::teleport($data, $payload), 'xp' => self::xp($data, $payload), default => null, }; } private static function kill(CompoundTag $data): string { self::setFloat($data, 'Health', 0.0); self::touchFloat($data, 'AbsorptionAmount', 0.0); return 'set their health to 0, so they respawn on their next join'; } private static function heal(CompoundTag $data): string { $max = PlayerData::maxHealth($data); self::setFloat($data, 'Health', $max); self::touchInt($data, 'HurtTime', 0); self::touchInt($data, 'DeathTime', 0); return 'restored their health to ' . rtrim(rtrim(number_format($max, 1, '.', ''), '0'), '.'); } private static function feed(CompoundTag $data): string { self::setInt($data, 'foodLevel', 20); self::setFloat($data, 'foodSaturationLevel', 20.0); self::touchFloat($data, 'foodExhaustionLevel', 0.0); self::touchInt($data, 'foodTickTimer', 0); return 'filled their hunger and saturation'; } private static function starve(CompoundTag $data): string { self::setInt($data, 'foodLevel', 0); self::setFloat($data, 'foodSaturationLevel', 0.0); self::touchFloat($data, 'foodExhaustionLevel', 0.0); return 'emptied their hunger and saturation'; } private static function gameMode(CompoundTag $data, string $mode): ?string { if (!isset(self::GAME_MODES[$mode])) { return null; } $target = self::GAME_MODES[$mode]; $current = self::readInt($data, 'playerGameType'); if ($current !== null && $current !== $target) { self::touchInt($data, 'previousPlayerGameType', $current); } self::setInt($data, 'playerGameType', $target); self::abilities($data, $target); return 'set their game mode to ' . $mode; } private static function abilities(CompoundTag $data, int $mode): void { $abilities = $data['abilities'] ?? null; if (!$abilities instanceof CompoundTag) { return; } $creative = $mode === self::GAME_MODES['creative']; $spectator = $mode === self::GAME_MODES['spectator']; self::touchInt($abilities, 'invulnerable', $creative || $spectator ? 1 : 0); self::touchInt($abilities, 'mayfly', $creative || $spectator ? 1 : 0); self::touchInt($abilities, 'instabuild', $creative ? 1 : 0); self::touchInt($abilities, 'mayBuild', $spectator || $mode === self::GAME_MODES['adventure'] ? 0 : 1); self::touchInt($abilities, 'flying', $spectator ? 1 : 0); } private static function teleport(CompoundTag $data, array $payload): ?string { if (!isset($payload['x'], $payload['y'], $payload['z'])) { return null; } $x = (float) $payload['x']; $y = (float) $payload['y']; $z = (float) $payload['z']; $dimension = (string) ($payload['dimension'] ?? 'minecraft:overworld'); self::setVector($data, 'Pos', [$x, $y, $z]); self::zeroVector($data, 'Motion'); self::touchFloat($data, 'fall_distance', 0.0); self::touchFloat($data, 'FallDistance', 0.0); self::setDimension($data, $dimension); $data->delete('RootVehicle'); return sprintf('moved them to %s %s %s in %s', $x, $y, $z, $dimension); } private static function xp(CompoundTag $data, array $payload): ?string { if (!isset($payload['levels'])) { return null; } $levels = (int) $payload['levels']; $current = self::readInt($data, 'XpLevel') ?? 0; $target = match ((string) ($payload['operation'] ?? 'set')) { 'add' => $current + $levels, 'remove' => $current - $levels, default => $levels, }; self::setInt($data, 'XpLevel', max(0, $target)); if ($target < 0) { self::setFloat($data, 'XpP', 0.0); self::setInt($data, 'XpTotal', 0); } return 'set their experience to level ' . max(0, $target); } private static function setDimension(CompoundTag $data, string $dimension): void { $tag = $data['Dimension'] ?? null; if ($tag instanceof IntValueTag) { $tag->setValue(self::LEGACY_DIMENSIONS[$dimension] ?? 0); return; } if ($tag instanceof StringTag) { $tag->setValue($dimension); return; } $data->set('Dimension', (new StringTag)->setValue($dimension)); } private static function setVector(CompoundTag $data, string $key, array $values): void { $list = $data[$key] ?? null; if ($list instanceof ListTag && count($list) >= count($values)) { foreach ($values as $index => $value) { $entry = $list[$index] ?? null; if ($entry instanceof FloatValueTag) { $entry->setValue($value); } elseif ($entry instanceof IntValueTag) { $entry->setValue((int) round($value)); } } return; } $fresh = (new ListTag)->setContentTag(TagType::TAG_Double); foreach ($values as $value) { $fresh[] = (new DoubleTag)->setValue($value); } $data->set($key, $fresh); } private static function zeroVector(CompoundTag $data, string $key): void { if (($data[$key] ?? null) instanceof ListTag) { self::setVector($data, $key, [0.0, 0.0, 0.0]); } } private static function readInt(CompoundTag $data, string $key): ?int { $tag = $data[$key] ?? null; return $tag instanceof IntValueTag || $tag instanceof FloatValueTag ? (int) $tag->getValue() : null; } private static function setFloat(CompoundTag $data, string $key, float $value): void { $tag = $data[$key] ?? null; if ($tag instanceof FloatValueTag) { $tag->setValue($value); } elseif ($tag instanceof IntValueTag) { $tag->setValue((int) round($value)); } else { $data->set($key, (new FloatTag)->setValue($value)); } } private static function setInt(CompoundTag $data, string $key, int $value): void { $tag = $data[$key] ?? null; if ($tag instanceof IntValueTag) { $tag->setValue($value); } elseif ($tag instanceof FloatValueTag) { $tag->setValue((float) $value); } else { $data->set($key, (new IntTag)->setValue($value)); } } private static function touchFloat(CompoundTag $data, string $key, float $value): void { if (isset($data[$key])) { self::setFloat($data, $key, $value); } } private static function touchInt(CompoundTag $data, string $key, int $value): void { if (isset($data[$key])) { self::setInt($data, $key, $value); } } private static function fail(string $message, int $status = 422): array { return ['ok' => false, 'status' => $status, 'message' => $message]; } private static function done(string $ran): array { return ['ok' => true, 'status' => 200, 'ran' => $ran]; } } 